  // Ice facet lines
  ctx.strokeStyle="#e0f2fe";ctx.lineWidth=1;ctx.globalAlpha=0.5;
  ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(r*0.1,r*0.1);ctx.stroke();
  ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(-r*0.1,r*0.1);ctx.stroke();
