  const pulse=0.83+0.17*stormPct;
  const sr=r*pulse;
  // Crystal body (octagon)
  ctx.beginPath();
  for(let i=0;i<8;i++){const a=i*Math.PI/4+ts*0.0015;ctx.lineTo(Math.cos(a)*sr,Math.sin(a)*sr);}
  ctx.closePath();
  ctx.fillStyle=isPeak?"#fde68a":"#fbbf24";
  ctx.shadowColor=isPeak?"#d97706":"#b45309";
