// ── Chrono Star — time star; apex phase = 3× ──
function drawChronoStar(ctx,r,ts,apexPct){
  ctx.save();
  const isApex=apexPct>0.85&&apexPct<0.97;
  ctx.shadowBlur=isApex?26:14;ctx.shadowColor=isApex?"#f0abfc":"#c084fc";
  // 6-point star
  const starR=r*0.75;const starInner=r*0.35;
  ctx.globalAlpha=isApex?0.9:0.65;
  const gStar=ctx.createRadialGradient(0,0,0,0,0,starR);
  gStar.addColorStop(0,"#fff");gStar.addColorStop(0.4,isApex?"#f0abfc":"#c084fc");gStar.addColorStop(1,"rgba(0,0,0,0)");
  ctx.fillStyle=gStar;
  ctx.beginPath();
  for(let cs=0;cs<6;cs++){
    const oA=cs*Math.PI/3-Math.PI/2+ts*(isApex?0.006:0.003);
    const iA=(cs+0.5)*Math.PI/3-Math.PI/2+ts*(isApex?0.006:0.003);
    cs===0?ctx.moveTo(Math.cos(oA)*starR,Math.sin(oA)*starR):ctx.lineTo(Math.cos(oA)*starR,Math.sin(oA)*starR);
    ctx.lineTo(Math.cos(iA)*starInner,Math.sin(iA)*starInner);
  }
  ctx.closePath();ctx.fill();
  // Time rings at apex
  if(isApex){
    for(let tr=1;tr<=2;tr++){
      ctx.globalAlpha=0.25;ctx.strokeStyle="#fae8ff";ctx.lineWidth=r*0.04;
      ctx.beginPath();ctx.arc(0,0,r*tr*0.3,0,Math.PI*2);ctx.stroke();
    }
  }
  ctx.globalAlpha=0.9;ctx.font=`${Math.round(r*0.38)}px sans-serif`;ctx.textAlign="center";ctx.textBaseline="middle";
  ctx.fillText(isApex?"⭐":"⏱️",0,0);
  ctx.restore();
}
// ── Prism Coil — spiraling prism; color sync = 3× ──
