type==="normal"?BASE_R*(rarity?.size||1):BASE_R;
    const pos=pickPos(baseR);
    let lifetime=cfg.targetLifetime;
    // World modifiers: Ocean Deep (8) — slower targets (calmer waters), longer lifetimes
    if(cfg.world===8)lifetime*=1.15;
    // World modifiers: Goblin Mines (6) — slightly faster targets (more chaotic) — short lifetimes
    if(cfg.world===6)lifetime*=0.92;
    if(activePwrRef.current.some(p=>p.type==="SLOW"&&p.endsAt>Date.now()))lifetime*=1.6;
    if(activePwrRef.current.some(p=>p.type==="FREEZE"&&p.endsAt>Date.now())){vx=0;vy=0;}
    // Phantom targets: very short lifetime (1100ms fixed) — catch it or lose it!
    if(type==="phantom")lifetime=1100;
    // Volatile targets: medium-short lifetime (2200ms) — defuse or explode
    if(type==="volatile")lifetime=2200;
    // Ninja targets: longer lifetime (3500ms) so visible window is still ~700ms
    if(type==="ninja")lifetime=3500;
    // Comet targets: very short lifetime (2800ms) — it flies across fast!
    if(type==="comet")lifetime=2800;
    // Ice Comet: similar short lifetime
    if(type==="icecomet")lifetime=3000;
    // Time Bomb: fixed 3s detonation fuse
    if(type==="timebomb")lifetime=3000;
    // Firefly: shorter lifetime (they dart away fast)
    if(type==="firefly")lifetime=Math.min(lifetime,2200);
    // Geode: slightly longer (2-tap mechanic)
    if(type==="geode")lifetime=Math.max(lifetime,3400);
    // Thunderbolt: very short (2s) — it falls fast
    if(type==="thunderbolt")lifetime=Math.min(lifetime,2000);
    // Quantum: medium lifetime — 3 taps needed before it vanishes
    if(type==="quantum")lifetime=Math.max(lifetime,4500);
    // Pinwheel: medium lifetime
    if(type==="pinwheel")lifetime=Math.max(lifetime,3500);
    // Supercell: medium - time to electrify
    if(type==="supercell")lifetime=Math.max(lifetime,3800);
    // Prism Bomb: medium
    if(type==="prismbomb")lifetime=Math.max(lifetime,3200);
    // Ice Cage: medium-long — give targets time to get trapped
    if(type==="icecage")lifetime=Math.max(lifetime,4000);
    // Solar Flare: medium lifetime — it expands over time
    if(type==="solarflare")lifetime=Math.max(lifetime,3500);
    // Magma: slightly longer — gives time to defuse
    if(type==="magma")lifetime=Math.max(lifetime,4000);
    // Chain Collector: medium lifetime
    if(type==="chaincollector")lifetime=Math.max(lifetime,3000);
    // Stardust: medium
    if(type==="stardust")lifetime=Math.max(lifetime,3200);
    // Star piece: short — catch them quick!
    if(type==="star_piece")lifetime=2000;
    // Bloom: medium lifetime
    if(type==="bloom")lifetime=Math.max(lifetime,3000);
    // Petal: short — catch petals quickly!
    if(type==="petal")lifetime=1800;
    // Reflector: medium
    if(type==="reflector")lifetime=Math.max(lifetime,3200);
    // Clockwork: medium-long so player can catch it
    if(type==="clockwork")lifetime=Math.max(lifetime,3600);
    // Gravity Orb: medium lifetime (allows it to pull targets for a while)
    if(type==="gravityorb")lifetime=Math.max(lifetime,3200);
    // Crystal Ball: medium-long (gives time to plan the tap)
    if(type==="crystalball")lifetime=Math.max(lifetime,3800);
    // Vortex: medium-long — give it time to pull targets
    if(type==="vortex")lifetime=Math.max(lifetime,4200);
    // Pixel: short — blink and you'll miss it!
    if(type==="pixel")lifetime=Math.min(lifetime,1800);
    // Neon Sign: medium — needs to cycle through all 3 colors
    if(type==="neon")lifetime=Math.max(lifetime,3600);
    // Lantern: medium
    if(type==="lantern")lifetime=Math.max(lifetime,3000);
    // Drift: medium-long — let it drift far from center
    if(type==="drift")lifetime=Math.max(lifetime,4000);
    // Nebula: medium — enough time to release star pieces
    if(type==="nebula")lifetime=Math.max(lifetime,3800);
    // Wisp: medium — toggle between moving/still
    if(type==="wisp")lifetime=Math.max(lifetime,3500);
    // Meteor: very short — fly across fast
    if(type==="meteor")lifetime=Math.min(lifetime,2600);
    // Aura: medium — let ring pulse a few times
    if(type==="aura")lifetime=Math.max(lifetime,3400);
    // Smoke Ring: medium — expands over 3s
    if(type==="smoke_ring")lifetime=3000;
    // Chain Bomb: short-ish — defuse urgency
    if(type==="chain_bomb")lifetime=Math.min(lifetime,2800);
    // Warp Gate: medium
    if(type==="warp_gate")lifetime=Math.max(lifetime,3000);
    // Mirage: medium-long — time to spot it
    if(type==="mirage")lifetime=Math.max(lifetime,4000);
    // Surge Ball: medium — enough for 1-2 arc cycles
    if(type==="surge_ball")lifetime=Math.max(lifetime,3200);
    // Ticking Clock: fixed 4s sweep — hand makes full rotation
    if(type==="ticking_clock")lifetime=4000;
    // Echo Pulse: 3.5s — rings expand and fade over that window
    if(type==="echo_pulse")lifetime=3500;
    // Gravity Well: medium-long — pull builds up over time
    if(type==="gravity_well")lifetime=Math.max(lifetime,4200);
    // Spectrum Orb: medium — hue cycles every 1.5s; gets 2 full rotations
    if(type==="spectrum_orb")lifetime=Math.max(lifetime,3000);
    // Shard Storm: medium — shards align every ~1.5s
    if(type==="shard_storm")lifetime=Math.max(lifetime,3500);
    // Pulse Nova: medium — 1.5s charge then 2s release window
    if(type==="pulse_nova")lifetime=3800;
    // Bubble Cluster: medium — 5 bubbles, tap soon before they drift apart
