        if(psPwr73.charges<=0){activePwrRef.current=activePwrRef.current.filter(p=>p.type!=="PULSE_SHIELD");setActivePwrDisp([...activePwrRef.current]);}
        else{setActivePwrDisp([...activePwrRef.current]);}
        gs.lives=Math.min(5,gs.lives+1); // restore the life
